WITH s AS (
  SELECT actor.login AS a, repo.id AS r FROM `githubarchive.month.*`
  WHERE _TABLE_SUFFIX BETWEEN '201501' AND '202606' AND type='WatchEvent' AND repo.id IN (2500088, 3470471, 3757512, 6452529, 11225014, 13124802, 14702444, 19257422, 21233191, 36437041, 37448451, 50874442, 52630616, 75255555, 88013053, 100346588, 116817549, 123606765, 143328315, 143846881, 145464445, 152572186, 168712350, 181399273, 201403923, 202291859, 214587193, 231921809, 235901813, 237222619, 254328371, 257787813, 271816968, 283046497, 285012857, 285092252, 289073337, 290495697, 294714234, 299482335, 304588125, 315977578, 325724738, 326404870, 327089870, 331293626, 342259394, 342728683, 348217288, 349372179, 351486934, 357728969, 358943289, 359995930, 360238600, 362806180, 365373172, 370119131, 371296634, 371644903, 380046663, 396569538, 396856161, 401275197, 420489845, 434630945, 438113412, 450188582, 461280850, 463728195, 464415161, 476820102, 480715758, 481955061, 488804911, 501725302, 510034344, 516192901, 521655652, 524510950, 543838169, 546358763, 547597394, 557075997, 572570113, 572984571, 573661753, 595832198, 597502256, 601834373, 605682921, 606164768, 607441698, 614695583, 619284964, 621803253, 621929252, 624681066, 628390075, 633262635, 637924634, 639096757, 642497346, 649170660, 654560183, 655949187, 656099147, 658928958, 660776503, 664872761, 671269505, 672387589, 676829188, 677829141, 686364232, 690825026, 704537857, 718873539, 725205304, 732124850, 736272311, 738290765, 763923484, 764723738, 771160970, 775009948, 775144062, 783445370, 787076358, 803014189, 839037098, 846729675, 863835427, 879336205, 881458615, 886966165, 893031915, 900550981, 914997268, 916009087, 925270205, 936400285, 952018616, 956472076, 963696290, 971447302, 973180254, 1002125012, 1017038703, 1028159967, 1044426027, 1066745758, 1076362809, 1090300896, 1125445550, 1144115288, 1147073855, 1167164255, 1170246605, 1177108326, 1217107102, 1234904564, 919987810)
  GROUP BY a, r ),
multi AS ( SELECT a FROM s GROUP BY a HAVING COUNT(*) >= 2 )
SELECT s.r AS repo_id, COUNT(*) AS stargazers, COUNTIF(s.a IN (SELECT a FROM multi)) AS network_stars
FROM s GROUP BY s.r
